float4 custom_e0be3ee871c932ce(float3 WorldPos, float4 Color, float endDistance, float startDistance, float4 Pos)
{
static const float4x4 DITHER_MATRIX = float4x4(
    1.0 / 17.0,  9.0 / 17.0,  3.0 / 17.0, 11.0 / 17.0,
    13.0 / 17.0,  5.0 / 17.0, 15.0 / 17.0,  7.0 / 17.0,
    4.0 / 17.0, 12.0 / 17.0,  2.0 / 17.0, 10.0 / 17.0,
    16.0 / 17.0,  8.0 / 17.0, 14.0 / 17.0,  6.0 / 17.0
);

float minHeight = 0.5;    
float maxHeight = 10.0;   
float minScale  = 0.1; 
float maxScale  = 4.0;  

float heightFactor = saturate((g_camPos.y - minHeight) / (maxHeight - minHeight));
float heightScale  = lerp(minScale, maxScale, heightFactor);

float scaledStartDist = startDistance * heightScale;
float scaledEndDist   = endDistance * heightScale;

float dist = distance(g_camPos, WorldPos);
float alpha = saturate((dist - scaledEndDist) / (scaledStartDist - scaledEndDist));

uint2 pixelPos = uint2(Pos.xy) % 4;
float ditherValue = DITHER_MATRIX[pixelPos.x][pixelPos.y];

clip(alpha - ditherValue);

return Color;
}

float4 custom_e6b5f23767e6067d(float4 color, float alphaCutoff)
{
   clip(color.a - alphaCutoff);
   return color;
}


struct PS_IN {
    float4 pos : SV_Position;
    float2 uv : TEXCOORD0;
    float3 normal : NORMAL;
    float3 viewNormal : NORMAL1;
    float3 worldNormal : NORMAL2;
    float3 worldPos : POSITION1;
    float3 worldTangent : TANGENT;
    nointerpolation uint instID : INSTANCEID;
};

struct PS_OUT {
    float4 target0 : SV_Target0;
    float4 target1 : SV_Target1;
    float4 target2 : SV_Target2;
    float4 target3 : SV_Target3;
    float4 target4 : SV_Target4;
};

PS_OUT main(PS_IN In)
{
    float3 node51_out = In.worldPos;
    float4 node22_out = (g_modelBaseColor.Sample(g_sampler, In.uv) * g_baseColorRate);
    float node23_out = g_params[1].x;
    float plx21_h = dot((node22_out).rgb, float3(0.299, 0.587, 0.114));
    float3 plx21_N = normalize(In.worldNormal);
    float3 plx21_T = normalize(In.worldTangent - dot(In.worldTangent, plx21_N) * plx21_N);
    float3 plx21_B = cross(plx21_N, plx21_T);
    float3x3 plx21_TBN = float3x3(plx21_T, plx21_B, plx21_N);
    float3 plx21_V = normalize(g_camPos - In.worldPos);
    float3 plx21_Vt = mul(plx21_TBN, plx21_V);
    float2 plx21_result = In.uv + plx21_Vt.xy * ((0.5 -plx21_h ) * (node23_out));
    float2 node21_out = plx21_result;
    float4 node20_out = (g_modelBaseColor.Sample(g_sampler, node21_out) * g_baseColorRate);
    float4 node25_out = g_params[2];
    float node26_out = g_params[3].x;
    float node29_out = g_params[4].x;
    float3 ssh24_N = normalize(In.worldNormal);
    float3 ssh24_T = normalize(In.worldTangent - dot(In.worldTangent, ssh24_N) * ssh24_N);
    float3 ssh24_B = cross(ssh24_N, ssh24_T);
    float3x3 ssh24_TBN = float3x3(ssh24_T, ssh24_B, ssh24_N);
    float3 ssh24_Lw = normalize(((node25_out).xyz));
    float3 ssh24_Lt = mul(ssh24_TBN, ssh24_Lw);
    float ssh24_h0 = dot(g_modelBaseColor.Sample(g_sampler, In.uv).rgb, float3(0.299,0.587,0.114));
    float ssh24_shadow = 1.0;
    float2 ssh24_uvStep = ssh24_Lt.xy * (node29_out) * 0.01;
    [unroll] for (int ssh24_i = 1; ssh24_i <= 8; ++ssh24_i)
    {
        float2 ssh24_suv = In.uv + ssh24_uvStep * ssh24_i;
        float ssh24_hs = dot(g_modelBaseColor.Sample(g_sampler, ssh24_suv).rgb, float3(0.299,0.587,0.114));
        float ssh24_expected = ssh24_h0 + ssh24_Lt.z * ssh24_i * 0.05;
        if (ssh24_hs > ssh24_expected)
            ssh24_shadow = min(ssh24_shadow, 1.0 - (ssh24_hs - ssh24_expected) * 5.0);
    }
    ssh24_shadow = saturate(lerp(1.0, ssh24_shadow, (node26_out)));
    float3 ssh24_result = (node20_out).rgb * ssh24_shadow;
    float4 node24_out = float4(ssh24_result, (node20_out).a);
    float node16_out = g_params[0].x;
    float node49_out = g_params[12].x;
    float nfh50_str = node16_out;
    float3 nfh50_rawN = In.worldNormal;
    float  nfh50_lenN = length(nfh50_rawN);
    float3 nfh50_N = (nfh50_lenN > 1e-5) ? (nfh50_rawN / nfh50_lenN) : float3(0.0, 1.0, 0.0);
    float3 nfh50_rawT = In.worldTangent - dot(In.worldTangent, nfh50_N) * nfh50_N;
    float  nfh50_lenT = length(nfh50_rawT);
    float3 nfh50_fb = (abs(nfh50_N.y) < 0.99) ? float3(0.0, 1.0, 0.0) : float3(1.0, 0.0, 0.0);
    float3 nfh50_T = (nfh50_lenT > 1e-5) ? (nfh50_rawT / nfh50_lenT) : normalize(cross(nfh50_fb, nfh50_N));
    float3 nfh50_B = cross(nfh50_N, nfh50_T);
    float2 nfh50_uv = node21_out;
    float2 nfh50_dim;
    g_modelBaseColor.GetDimensions(nfh50_dim.x, nfh50_dim.y);
    float2 nfh50_tx = max(node49_out, 0.01) / max(nfh50_dim, 1.0);
    float2 nfh50_duvdx = ddx(nfh50_uv) * nfh50_dim;
    float2 nfh50_duvdy = ddy(nfh50_uv) * nfh50_dim;
    float  nfh50_rho = max(dot(nfh50_duvdx, nfh50_duvdx), dot(nfh50_duvdy, nfh50_duvdy));
    float  nfh50_lod = max(0.5 * log2(max(nfh50_rho, 1e-8)) + (0.0f), 0.0);
    float nfh50_h_tl = dot(g_modelBaseColor.SampleLevel(g_sampler, nfh50_uv + float2(-1.0, -1.0) * nfh50_tx, nfh50_lod).rgb, float3(0.2126, 0.7152, 0.0722));
    float nfh50_h_t = dot(g_modelBaseColor.SampleLevel(g_sampler, nfh50_uv + float2(0.0, -1.0) * nfh50_tx, nfh50_lod).rgb, float3(0.2126, 0.7152, 0.0722));
    float nfh50_h_tr = dot(g_modelBaseColor.SampleLevel(g_sampler, nfh50_uv + float2(1.0, -1.0) * nfh50_tx, nfh50_lod).rgb, float3(0.2126, 0.7152, 0.0722));
    float nfh50_h_l = dot(g_modelBaseColor.SampleLevel(g_sampler, nfh50_uv + float2(-1.0, 0.0) * nfh50_tx, nfh50_lod).rgb, float3(0.2126, 0.7152, 0.0722));
    float nfh50_h_c = dot(g_modelBaseColor.SampleLevel(g_sampler, nfh50_uv + float2(0.0, 0.0) * nfh50_tx, nfh50_lod).rgb, float3(0.2126, 0.7152, 0.0722));
    float nfh50_h_r = dot(g_modelBaseColor.SampleLevel(g_sampler, nfh50_uv + float2(1.0, 0.0) * nfh50_tx, nfh50_lod).rgb, float3(0.2126, 0.7152, 0.0722));
    float nfh50_h_bl = dot(g_modelBaseColor.SampleLevel(g_sampler, nfh50_uv + float2(-1.0, 1.0) * nfh50_tx, nfh50_lod).rgb, float3(0.2126, 0.7152, 0.0722));
    float nfh50_h_b = dot(g_modelBaseColor.SampleLevel(g_sampler, nfh50_uv + float2(0.0, 1.0) * nfh50_tx, nfh50_lod).rgb, float3(0.2126, 0.7152, 0.0722));
    float nfh50_h_br = dot(g_modelBaseColor.SampleLevel(g_sampler, nfh50_uv + float2(1.0, 1.0) * nfh50_tx, nfh50_lod).rgb, float3(0.2126, 0.7152, 0.0722));
    float nfh50_gx = (nfh50_h_tl + 2.0 * nfh50_h_l + nfh50_h_bl)
                            - (nfh50_h_tr + 2.0 * nfh50_h_r + nfh50_h_br);
    float nfh50_gy = (nfh50_h_tl + 2.0 * nfh50_h_t + nfh50_h_tr)
                            - (nfh50_h_bl + 2.0 * nfh50_h_b + nfh50_h_br);
    nfh50_gy = ((0.0f) > 0.5) ? -nfh50_gy : nfh50_gy;
    float3 nfh50_texN = normalize(float3(nfh50_gx * nfh50_str, nfh50_gy * nfh50_str, 1.0));
    float nfh50_camDist = length(g_camPos - In.worldPos);
    float nfh50_fade = 1.0 - saturate((nfh50_camDist - (15.0f))
                                            / max(25.0f, 1e-4));
    nfh50_texN = normalize(lerp(float3(0.0, 0.0, 1.0), nfh50_texN, nfh50_fade));
    float3 nfh50_result = normalize(nfh50_texN.x * nfh50_T + nfh50_texN.y * nfh50_B + nfh50_texN.z * nfh50_N);
    float3 node50_out = nfh50_result;
    float4 node31_out = g_params[5];
    float node32_out = g_params[6].x;
    float3 ewr30_tN = nfh50_texN;
    float ewr30_conv = ddx(ewr30_tN.x) + ddy(ewr30_tN.y);
    float ewr30_edge = saturate(ewr30_conv * (node32_out));
    float3 ewr30_result = lerp((node20_out).rgb, (node31_out).rgb, ewr30_edge);
    float4 node30_out = float4(ewr30_result, (node20_out).a);
    float4 node43_out = node24_out + node30_out;
    float node46_out = g_params[10].x;
    float4 node44_out = custom_e6b5f23767e6067d(node43_out, node46_out);
    float node54_out = g_params[14].x;
    float node53_out = g_params[13].x;
    float4 node56_out = In.pos;
    float4 node52_out = custom_e0be3ee871c932ce(node51_out, node44_out, node54_out, node53_out, node56_out);
    float4 node6_out = (g_modelMetalRough.Sample(g_sampler, In.uv) * float4(1.0, g_roughnessRate, g_metallicRate, 1.0));
    float4 node35_out = g_params[7];
    float3 tksv34_tN = nfh50_texN;
    float tksv34_var = (length(ddx(tksv34_tN)) + length(ddy(tksv34_tN))) * ((node35_out).x);
    float tksv34_result = saturate(lerp((node6_out.g), 1.0, saturate(tksv34_var)));
    float node34_out = tksv34_result;
    float4 node38_out = g_params[9];
    float node48_out = g_params[11].x;
    PS_OUT o;
    o.target0 = float4((node52_out).xyz, node6_out.b);
    o.target1 = float4((nfh50_result) * 0.5 + 0.5, node34_out);
    o.target2 = float4(In.worldPos, 1.0);
    o.target3 = float4((node38_out).xyz, node48_out);
    o.target4 = float4(0,0,0,0);
    return o;
}

